import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
dfs = []
for i in range(1, 7):
    try:
        df = pd.read_csv(f"experiment_{i}_csv")
        df['source'] = f'exp_{i}'
        dfs.append(df)
    except:
        pass

all_data = pd.concat(dfs, ignore_index=True)
print("Columns:", all_data.columns.tolist())
print("\nShape:", all_data.shape)
print("\n--- All correlations with JobThroughput ---")
for col in all_data.select_dtypes('number').columns:
    if col != 'JobThroughput' and col != 'unit_id':
        corr = all_data[col].corr(all_data['JobThroughput'])
        print(f"{col:40s} {corr:8.4f}")

print("\n--- Dose-response for CoolingSetpoint ---")
if 'CoolingSetpoint' in all_data.columns:
    for val in sorted(all_data['CoolingSetpoint'].dropna().unique()):
        subset = all_data[all_data['CoolingSetpoint'] == val]
        print(f"  Setpoint={val}: mean throughput={subset['JobThroughput'].mean():.2f} (n={len(subset)})")

# Look for fan-related variables
print("\n--- Variables with 'fan' or 'noise' or 'airflow' in name ---")
for col in all_data.columns:
    if any(x in col.lower() for x in ['fan', 'noise', 'airflow', 'vibration', 'speed', 'rpm']):
        print(f"  {col}: {all_data[col].describe().to_string()}")
